INSERT INTO `resources` (`id`, `code`, `name`, `category_id`, `room_id`, `department_id`, `capacity`, `description`, `status`, `requires_approval`, `created_at`, `updated_at`) VALUES
(1, 'CSE-LAB-01', 'AI & Machine Learning Lab', 1, 1, 1, 40, 'GPU workstations with Python, PyTorch and TensorFlow pre-installed for model training sessions.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(2, 'CSE-LAB-02', 'Data Structures & Algorithms Lab', 1, 2, 1, 60, 'Sixty-seat programming lab used for contests, practicals and coding workshops.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(3, 'CSE-LAB-03', 'Database Systems Lab', 1, 3, 1, 60, 'MySQL, MongoDB and PostgreSQL servers available on every workstation.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(4, 'CSE-LAB-04', 'Cyber Security Lab', 1, 4, 1, 30, 'Isolated network segment for penetration-testing and forensics practicals.', 'maintenance', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(5, 'CSE-LAB-05', 'Cloud & DevOps Lab', 1, 5, 1, 40, 'Containers, CI/CD tooling and cloud sandboxes for DevOps coursework.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(6, 'ECE-LAB-01', 'Digital Electronics Lab', 2, 6, 2, 30, 'Trainer kits, logic analysers and function generators on 15 benches.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(7, 'ECE-LAB-02', 'VLSI Design Lab', 2, 7, 2, 24, 'EDA workstations running Cadence and Xilinx toolchains.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(8, 'ECE-LAB-03', 'Embedded Systems & IoT Lab', 2, 8, 2, 30, 'ARM boards, Raspberry Pi and sensor kits for embedded projects.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(9, 'ECE-LAB-04', 'Communication Systems Lab', 2, 9, 2, 24, 'Spectrum analysers and SDR kits for communication experiments.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(10, 'ME-LAB-01', 'CAD/CAM Lab', 1, 10, 3, 36, 'SolidWorks and ANSYS workstations with a CNC simulation bay.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(11, 'SCI-LAB-01', 'Physics Laboratory', 3, 11, 6, 30, 'Optics, modern physics and mechanics experiments.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(12, 'SCI-LAB-02', 'Chemistry Laboratory', 3, 12, 6, 30, 'Fume-hood equipped laboratory for organic and inorganic practicals.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(13, 'SCI-LAB-03', 'Biotechnology Research Lab', 3, 13, 7, 20, 'PCR, gel electrophoresis and cell-culture facilities.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(14, 'SCI-LAB-04', 'Microbiology Lab', 3, 14, 7, 20, 'Incubators, autoclave and laminar-flow cabinets.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(15, 'CR-ENG-301', 'Lecture Room E-301', 4, 15, 1, 70, 'Tiered lecture room with dual projectors and lecture capture.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(16, 'CR-ENG-302', 'Lecture Room E-302', 4, 16, 1, 70, 'Tiered lecture room with smart board.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(17, 'CR-ENG-303', 'Lecture Room E-303', 4, 17, 2, 60, 'Flat-floor classroom suited to tutorials and examinations.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(18, 'CR-SCI-103', 'Lecture Room S-103', 4, 18, 6, 80, 'Large lecture room with demonstration bench.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(19, 'CR-SCI-104', 'Lecture Room S-104', 4, 19, 6, 60, 'Standard lecture room with projector.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(20, 'CR-MGT-101', 'Case Study Room M-101', 4, 20, 5, 50, 'Horseshoe seating built for case-method teaching.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(21, 'CR-MGT-102', 'Case Study Room M-102', 4, 21, 5, 50, 'Horseshoe seating with dual displays.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(22, 'DR-LIB-01', 'Group Study Room 1', 5, 22, 8, 8, 'Glass-walled room with whiteboard and display. Instant confirmation.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(23, 'DR-LIB-02', 'Group Study Room 2', 5, 23, 8, 8, 'Quiet room for project discussions. Instant confirmation.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(24, 'DR-LIB-03', 'Group Study Room 3', 5, 24, 8, 10, 'Ten-seat room with wall display. Instant confirmation.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(25, 'DR-LIB-04', 'Group Study Room 4', 5, 25, 8, 6, 'Compact room for pair programming and viva practice. Instant confirmation.', 'available', 0, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(26, 'HALL-MGT-A', 'Seminar Hall A', 6, 26, 5, 150, 'Air-conditioned seminar hall with stage, PA system and recording.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(27, 'HALL-ENG-B', 'Seminar Hall B', 6, 27, 1, 120, 'Seminar hall used for guest lectures and workshops.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(28, 'HALL-LIB-IS', 'Innovation Studio', 6, 28, 8, 40, 'Flexible makerspace with movable furniture and demo area.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(29, 'AUD-MAIN', 'Convocation Auditorium', 7, 29, NULL, 800, 'Main auditorium with stage lighting, live-stream rig and green rooms.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(30, 'EQ-PRJ-01', 'Portable Projector Kit 1', 8, 30, NULL, 1, 'Full-HD projector with screen, HDMI/VGA leads and extension.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(31, 'EQ-PRJ-02', 'Portable Projector Kit 2', 8, 30, NULL, 1, 'Full-HD projector with screen, HDMI/VGA leads and extension.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(32, 'EQ-CAM-01', 'DSLR Camera & Tripod Kit', 8, 31, NULL, 1, 'Camera body, two lenses, tripod and lighting for event coverage.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(33, 'EQ-VR-01', 'VR Headset Set (6 units)', 8, 31, NULL, 6, 'Six standalone VR headsets with controllers for immersive-learning projects.', 'maintenance', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(34, 'EQ-IOT-01', 'Raspberry Pi & Arduino Project Bundle', 8, 32, NULL, 10, 'Ten Raspberry Pi 4 boards, Arduino Uno kits and sensor packs.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(35, 'EQ-OSC-01', 'Digital Oscilloscope Set', 8, 32, 2, 4, 'Four 100 MHz oscilloscopes with probes for off-lab experiments.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49'),
(36, 'EQ-3DP-01', '3D Printer Station', 8, 33, 3, 2, 'Dual-nozzle FDM printer with filament starter pack.', 'available', 1, '2025-09-28 12:33:49', '2026-11-22 07:03:49');
